return {["挂机事件表"]={["1"]={["id"]=1,["showDesc"]=[[你懵懵懂懂，来到池塘边打鱼。]],["taskId"]=10001,["taskType"]=1,["time"]=0},["10"]={["id"]=10,["showDesc"]=[[你初来乍到，被江湖上的一家酒楼收留，在酒楼里给客人斟茶倒水。]],["taskId"]=10010,["taskType"]=1,["time"]=0},["100"]={["id"]=100,["showDesc"]=[[你在江湖名镇四海，有人告知天都峰有外族高手来袭，你决定前去保卫天都。]],["taskId"]=10110,["taskType"]=1,["time"]=0},["101"]={["id"]=101,["showDesc"]=[[天都峰下，只见一个白熊一般的罗刹人挥舞着一把千斤巨锤，逼得众人不能近身，你抽出兵器与他缠斗在一起。]],["taskId"]=10110,["taskType"]=2,["time"]=5},["102"]={["id"]=102,["showDesc"]=[[你刚踏进天都峰，感觉有人在周边潜伏，随手一掌向树上打去，竟跳出一名精通忍术的东瀛高手！]],["taskId"]=10110,["taskType"]=2,["time"]=5},["103"]={["id"]=103,["showDesc"]=[[你觉得有点累了，想停下来歇一歇。]],["taskId"]=10110,["taskType"]=3,["time"]=0},["104"]={["id"]=104,["showDesc"]=[[你联袂中原几大高手，在天都峰上怒挫强敌，连连击败外族高手，可谓酣畅淋漓。]],["taskId"]=10110,["taskType"]=4,["time"]=0},["105"]={["id"]=105,["showDesc"]=[[见你出马，来犯的外族高手闻风而逃，天都之围登时被解。]],["taskId"]=10110,["taskType"]=5,["time"]=0},["107"]={["id"]=107,["showDesc"]=[[你极富盛名，中原外的高手见到你也不敢放肆，对你来说，保卫天都和巡山视察并无差别。]],["taskId"]=10110,["taskType"]=6,["time"]=0},["108"]={["id"]=108,["showDesc"]=[[不用这么快，外族高手也不是每天都来的。]],["taskId"]=10110,["taskType"]=7,["time"]=0},["11"]={["id"]=11,["showDesc"]=[[你抬眼一瞧，店里居然来了位气度不凡的千金小姐，你连忙跑过去给她倒了杯水。]],["taskId"]=10010,["taskType"]=2,["time"]=5},["12"]={["id"]=12,["showDesc"]=[[你抬眼一瞧，店里来了一位凶神恶煞的大汉正招呼你过去倒水，吓得你赶快转过身去，假装没看到他！]],["taskId"]=10010,["taskType"]=2,["time"]=5},["13"]={["id"]=13,["showDesc"]=[[你觉得有点累了，想停下来歇一歇。]],["taskId"]=10010,["taskType"]=3,["time"]=0},["14"]={["id"]=14,["showDesc"]=[[倒了一天的水，穷苦的日子真是不容易啊！今后要努力成为一代大侠才行！]],["taskId"]=10010,["taskType"]=4,["time"]=0},["15"]={["id"]=15,["showDesc"]=[[你熟练地为店里的每一位客人斟上热茶，获得了客人们的一致好评。]],["taskId"]=10010,["taskType"]=5,["time"]=0},["17"]={["id"]=17,["showDesc"]=[[也许是你太无聊了，居然跑去酒楼给别人斟茶递水。]],["taskId"]=10010,["taskType"]=6,["time"]=0},["18"]={["id"]=18,["showDesc"]=[[别太快了，小心打翻茶水！]],["taskId"]=10010,["taskType"]=7,["time"]=0},["19"]={["id"]=19,["showDesc"]=[[你学了点假把式，来到华山村帮老农们看守谷场。]],["taskId"]=10020,["taskType"]=1,["time"]=0},["2"]={["id"]=2,["showDesc"]=[[你跳进水里一番摸索，结果捞了个寂寞。]],["taskId"]=10001,["taskType"]=2,["time"]=5},["20"]={["id"]=20,["showDesc"]=[[有几只麻雀飞进谷场偷吃谷物，你掏出扫帚一顿打，虽然毛都没打到一根，但还是把它们吓跑了。]],["taskId"]=10020,["taskType"]=2,["time"]=5},["21"]={["id"]=21,["showDesc"]=[[一道黑影闪电般地钻进了谷堆中，你飞起一脚将它踹飞，好家伙，原来是一只油光水滑的大黑耗子！]],["taskId"]=10020,["taskType"]=2,["time"]=5},["22"]={["id"]=22,["showDesc"]=[[你觉得有点累了，想停下来歇一歇。]],["taskId"]=10020,["taskType"]=3,["time"]=0},["23"]={["id"]=23,["showDesc"]=[[看了一天的场子，你觉得颇有些劳累，日后还要好好努力才行！]],["taskId"]=10020,["taskType"]=4,["time"]=0},["24"]={["id"]=24,["showDesc"]=[[你扛着扫帚来回巡视，看你满脸凶神恶煞，小畜生们都不敢靠近偷吃。]],["taskId"]=10020,["taskType"]=5,["time"]=0},["26"]={["id"]=26,["showDesc"]=[[虽然以你的实力不用再干这个了，但你还是坚持要替老农看守谷场，让老农们非常无语。]],["taskId"]=10020,["taskType"]=6,["time"]=0},["27"]={["id"]=27,["showDesc"]=[[淡定点，看守谷场不需要那么快！]],["taskId"]=10020,["taskType"]=7,["time"]=0},["28"]={["id"]=28,["showDesc"]=[[你练了几把力气，决定去平安小镇的码头搬运货物。]],["taskId"]=10030,["taskType"]=1,["time"]=0},["29"]={["id"]=29,["showDesc"]=[[工头一声吆喝，你们一行人呼啦啦上船招呼，将船上的富商老板吓个半死。]],["taskId"]=10030,["taskType"]=2,["time"]=5},["3"]={["id"]=3,["showDesc"]=[[你一竿子下去，正中鱼儿的脑门，今天的晚饭有着落了。]],["taskId"]=10001,["taskType"]=2,["time"]=5},["30"]={["id"]=30,["showDesc"]=[[一位工友向你哭诉被人骗了工钱，你怒不可遏，带上一伙兄弟上船讨说法，对方赶紧把工钱交了回来。]],["taskId"]=10030,["taskType"]=2,["time"]=5},["31"]={["id"]=31,["showDesc"]=[[你觉得有点累了，想停下来歇一歇。]],["taskId"]=10030,["taskType"]=3,["time"]=0},["32"]={["id"]=32,["showDesc"]=[[搬了一天的货，累得你全身瘫软，你开始明白混江湖光有力气还不行，还是得有文化。]],["taskId"]=10030,["taskType"]=4,["time"]=0},["33"]={["id"]=33,["showDesc"]=[[你一咬牙，扛起七八十斤的货物，一口气将它们全部搬到马车上。]],["taskId"]=10030,["taskType"]=5,["time"]=0},["35"]={["id"]=35,["showDesc"]=[[以你现在的身手还去码头上搬运货物，其他工人怕是都不敢抢你生意。]],["taskId"]=10030,["taskType"]=6,["time"]=0},["36"]={["id"]=36,["showDesc"]=[[你也太快了，别把货给砸了！]],["taskId"]=10030,["taskType"]=7,["time"]=0},["37"]={["id"]=37,["showDesc"]=[[你在江湖上摸爬滚打，学了些花架子，决定去杭州摆摊卖艺。]],["taskId"]=10040,["taskType"]=1,["time"]=0},["38"]={["id"]=38,["showDesc"]=[[你摆了个摊子，决定表演一手胸口碎大石，一锤子下去，大石没碎你感觉肋骨要碎。]],["taskId"]=10040,["taskType"]=2,["time"]=5},["39"]={["id"]=39,["showDesc"]=[[你摆了个摊子，大吼大叫打了几个来回，十分卖力，赢得了周围观众的吆喝声。]],["taskId"]=10040,["taskType"]=2,["time"]=5},["4"]={["id"]=4,["showDesc"]=[[你觉得有点累了，想停下来歇一歇。]],["taskId"]=10001,["taskType"]=3,["time"]=0},["40"]={["id"]=40,["showDesc"]=[[你觉得有点累了，想停下来歇一歇。]],["taskId"]=10040,["taskType"]=3,["time"]=0},["41"]={["id"]=41,["showDesc"]=[[在街上卖了一天艺，感觉一天下来混江湖的经验积累了不少。]],["taskId"]=10040,["taskType"]=4,["time"]=0},["42"]={["id"]=42,["showDesc"]=[[你来回表演了几套招数，周围传来稀稀拉拉的掌声。]],["taskId"]=10040,["taskType"]=5,["time"]=0},["44"]={["id"]=44,["showDesc"]=[[以你的身手还来街头卖艺，也不怕砸别人饭碗。]],["taskId"]=10040,["taskType"]=6,["time"]=0},["45"]={["id"]=45,["showDesc"]=[[别急，速度太快了观众都看不清了。]],["taskId"]=10040,["taskType"]=7,["time"]=0},["46"]={["id"]=46,["showDesc"]=[[你在江湖上学了些本事，来到一家铁匠铺帮忙修理武器。]],["taskId"]=10050,["taskType"]=1,["time"]=0},["47"]={["id"]=47,["showDesc"]=[[你单手提着刀，卖力打磨。不一会儿，手中的刀被你磨得焕然一新。]],["taskId"]=10050,["taskType"]=2,["time"]=5},["48"]={["id"]=48,["showDesc"]=[[你捧着一把断剑左思右想，最后还是决定把它送到铁匠师傅的手上。]],["taskId"]=10050,["taskType"]=2,["time"]=5},["49"]={["id"]=49,["showDesc"]=[[你觉得有点累了，想停下来歇一歇。]],["taskId"]=10050,["taskType"]=3,["time"]=0},["5"]={["id"]=5,["showDesc"]=[[池塘里的鱼快被你打完了，你累得满头大汗，停止了继续打鱼的想法。]],["taskId"]=10001,["taskType"]=4,["time"]=0},["50"]={["id"]=50,["showDesc"]=[[在铁匠铺忙活了一天，也算是没有白忙活。]],["taskId"]=10050,["taskType"]=4,["time"]=0},["51"]={["id"]=51,["showDesc"]=[[你叮叮当当敲了一阵，把残破的兵器都修好了！]],["taskId"]=10050,["taskType"]=5,["time"]=0},["53"]={["id"]=53,["showDesc"]=[[这样的工作对你来讲已经没什么收益了，但还是硬着头皮继续干下去。]],["taskId"]=10050,["taskType"]=6,["time"]=0},["54"]={["id"]=54,["showDesc"]=[[哎哎哎！别干这么快，小心弄砸了！]],["taskId"]=10050,["taskType"]=7,["time"]=0},["55"]={["id"]=55,["showDesc"]=[[你在江湖上颇有几分能耐，决定前往长安镖局做个临时镖师。]],["taskId"]=10060,["taskType"]=1,["time"]=0},["56"]={["id"]=56,["showDesc"]=[[突然间，林中闪过几道黑影，你和身旁押运的镖师拔出武器大声质问：“是谁？”结果只是几头受惊的小鹿。]],["taskId"]=10060,["taskType"]=2,["time"]=5},["57"]={["id"]=57,["showDesc"]=[[小道上枝桠密布，粮车寸步难行，你只得拿出开山刀在前方开路，后面的几个兄弟推着粮车前行。]],["taskId"]=10060,["taskType"]=2,["time"]=5},["58"]={["id"]=58,["showDesc"]=[[你觉得有点累了，想停下来歇一歇。]],["taskId"]=10060,["taskType"]=3,["time"]=0},["59"]={["id"]=59,["showDesc"]=[[不知走了多久的路，这趟镖总算是送到了。]],["taskId"]=10060,["taskType"]=4,["time"]=0},["6"]={["id"]=6,["showDesc"]=[[你拿出竿子，对小河一阵乱叉，叉出了几个不知名的东西。]],["taskId"]=10001,["taskType"]=5,["time"]=0},["60"]={["id"]=60,["showDesc"]=[[这一路上顺风顺水，没啥意外发生，让你直打哈欠。]],["taskId"]=10060,["taskType"]=5,["time"]=0},["62"]={["id"]=62,["showDesc"]=[[以你的江湖地位来说，做一个普通的镖师已经不合适了，但你依然选择这么做。]],["taskId"]=10060,["taskType"]=6,["time"]=0},["63"]={["id"]=63,["showDesc"]=[[别太着急了！送镖讲究小心驶得万年船！]],["taskId"]=10060,["taskType"]=7,["time"]=0},["64"]={["id"]=64,["showDesc"]=[[你的武功水平已经不错了，被金牛武馆请去当临时教习。]],["taskId"]=10070,["taskType"]=1,["time"]=0},["65"]={["id"]=65,["showDesc"]=[[来了几位公子哥儿找你学拳，才练了几下就叫苦连天的，气得你给了他们几巴掌！]],["taskId"]=10070,["taskType"]=2,["time"]=5},["66"]={["id"]=66,["showDesc"]=[[武馆又来一位上门踢馆的，你上去跟他比划了几招，打得有来有回，武馆弟子连连叫好！]],["taskId"]=10070,["taskType"]=2,["time"]=5},["67"]={["id"]=67,["showDesc"]=[[你觉得有点累了，想停下来歇一歇。]],["taskId"]=10070,["taskType"]=3,["time"]=0},["68"]={["id"]=68,["showDesc"]=[[你教了一天的武功，也不知武馆那几个兔崽子学的怎么样了。]],["taskId"]=10070,["taskType"]=4,["time"]=0},["69"]={["id"]=69,["showDesc"]=[[你来回演示了几套拳法，随后便让武馆弟子自己练习去了。]],["taskId"]=10070,["taskType"]=5,["time"]=0},["71"]={["id"]=71,["showDesc"]=[[以你现在的江湖威望，再去武馆教人未免有些吓人，不过你并不在意。]],["taskId"]=10070,["taskType"]=6,["time"]=0},["72"]={["id"]=72,["showDesc"]=[[武馆师傅：慢一点！你教的太快了，武馆弟子根本学不过来！]],["taskId"]=10070,["taskType"]=7,["time"]=0},["73"]={["id"]=73,["showDesc"]=[[你在江湖上颇有威名，决定加入一支由武林豪侠组成的精英小队，与外族敌寇大干一场。]],["taskId"]=10080,["taskType"]=1,["time"]=0},["74"]={["id"]=74,["showDesc"]=[[你冲进人堆，指南打北，一众敌寇被你杀的片甲不留，狼狈逃窜！]],["taskId"]=10080,["taskType"]=2,["time"]=5},["75"]={["id"]=75,["showDesc"]=[[你们埋伏在暗，突然杀出，杀得敌寇措手不及，丢盔弃甲而逃。]],["taskId"]=10080,["taskType"]=2,["time"]=5},["76"]={["id"]=76,["showDesc"]=[[你觉得有点累了，想停下来歇一歇。]],["taskId"]=10080,["taskType"]=3,["time"]=0},["77"]={["id"]=77,["showDesc"]=[[你与一众敌寇周旋了半天，当真是酣畅淋漓！]],["taskId"]=10080,["taskType"]=4,["time"]=0},["78"]={["id"]=78,["showDesc"]=[[你们深入敌营，在敌人的老窝里给了他们迎头痛击。]],["taskId"]=10080,["taskType"]=5,["time"]=0},["8"]={["id"]=8,["showDesc"]=[[以你如今的身份，这样的工作已经不适合你了，但你现在就想要干这个。]],["taskId"]=10001,["taskType"]=6,["time"]=0},["80"]={["id"]=80,["showDesc"]=[[对你来说，与敌寇周旋无异于小打小闹，但你还是想和他们玩一玩。]],["taskId"]=10080,["taskType"]=6,["time"]=0},["81"]={["id"]=81,["showDesc"]=[[慢点！与敌寇周旋千万不能打草惊蛇！]],["taskId"]=10080,["taskType"]=7,["time"]=0},["82"]={["id"]=82,["showDesc"]=[[你江湖地位不凡，武林盟特意请你过去，拜托你将一份军机密函送往边关前线。]],["taskId"]=10090,["taskType"]=1,["time"]=0},["83"]={["id"]=83,["showDesc"]=[[你从怀中掏出一张地图看了看，辨清方向后，决定走一条隐秘安全的荒芜小道。]],["taskId"]=10090,["taskType"]=2,["time"]=5},["84"]={["id"]=84,["showDesc"]=[[只见一伙黑衣人四面来袭，似是冲着你怀中的密函而来，你抽出武器沉着应战，片刻便将这伙乌合之众赶跑了。]],["taskId"]=10090,["taskType"]=2,["time"]=5},["85"]={["id"]=85,["showDesc"]=[[你觉得有点累了，想停下来歇一歇。]],["taskId"]=10090,["taskType"]=3,["time"]=0},["86"]={["id"]=86,["showDesc"]=[[你谨慎前行，经过几番彻夜的劳累，终将密函送到边关前线。]],["taskId"]=10090,["taskType"]=4,["time"]=0},["87"]={["id"]=87,["showDesc"]=[[你一路风驰电掣，不多时便将密函安全送到。]],["taskId"]=10090,["taskType"]=5,["time"]=0},["89"]={["id"]=89,["showDesc"]=[[哪怕将密函送往前线，这种事对你来说也只是小事一件，但你还是顺手揽下了这个工作。]],["taskId"]=10090,["taskType"]=6,["time"]=0},["9"]={["id"]=9,["showDesc"]=[[你实在是闲的发慌，才会去玩这些小屁孩才玩的东西。]],["taskId"]=10001,["taskType"]=7,["time"]=0},["90"]={["id"]=90,["showDesc"]=[[你速度太快了，别人密函还没写好呢！]],["taskId"]=10090,["taskType"]=7,["time"]=0},["91"]={["id"]=91,["showDesc"]=[[你在江湖上声名赫赫，听闻朝中忠臣受奸人迫害，被关入沧州大牢，决定前往解救。]],["taskId"]=10100,["taskType"]=1,["time"]=0},["92"]={["id"]=92,["showDesc"]=[[你趁夜打晕一个狱卒，并换上他的衣物潜入大牢之中。经你一番精巧的布置周旋，你成功接近了牢狱深处。]],["taskId"]=10100,["taskType"]=2,["time"]=5},["93"]={["id"]=93,["showDesc"]=[[你单枪匹马，直闯大牢深处，将众狱卒杀的片甲不留。经你一番苦战，对方渐渐等来高手支援，万般无奈下你只得先行退去。]],["taskId"]=10100,["taskType"]=2,["time"]=5},["94"]={["id"]=94,["showDesc"]=[[你觉得有点累了，想停下来歇一歇。]],["taskId"]=10100,["taskType"]=3,["time"]=0},["95"]={["id"]=95,["showDesc"]=[[经过你长时间的谋划潜伏，终于将一位忠心老臣从牢狱中救出。]],["taskId"]=10100,["taskType"]=4,["time"]=0},["96"]={["id"]=96,["showDesc"]=[[你悄无声息，潜入狱中，将狱中忠良一一救出，可谓神不知鬼不觉。]],["taskId"]=10100,["taskType"]=5,["time"]=0},["98"]={["id"]=98,["showDesc"]=[[以你现在的影响力，足以震慑整个中原，哪怕是解救忠良，对你来说也是小事一桩。]],["taskId"]=10100,["taskType"]=6,["time"]=0},["99"]={["id"]=99,["showDesc"]=[[少侠切勿操之过急！一但有失，狱中大臣恐有性命之忧。]],["taskId"]=10100,["taskType"]=7,["time"]=0}}}00000000000